using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using PowerPointIntelligence.AddIn;
internal static class ContextPanelModelTests
{
    private static int count;
    private static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL context model "+name);count++;}
    private static void Reject(Action action,string name){try{action();}catch(Exception ex) when(ex is InvalidDataException||ex is InvalidOperationException||ex is ArgumentNullException){count++;return;}throw new Exception("FAIL expected context rejection "+name);}
    private static ContextDescriptor D(int id,string managed=null){return new ContextDescriptor {ShapeId=id,IsShape=true,ManagedType=managed,CanText=true,CanFill=true,CanOutline=true,CanFont=true};}
    private static ContextSnapshot Build(params ContextDescriptor[] items){return ContextPanelModel.Build(items,ContextPanelModel.SelectionKey(12,100,items.Select(d=>d.ShapeId)));}
    private static bool Fits(Rectangle child,Rectangle area){return child.Left>=area.Left&&child.Top>=area.Top&&child.Right<=area.Right&&child.Bottom<=area.Bottom;}
    internal static void Run()
    {
        count=0;Check(ContextPanelModel.Build(new ContextDescriptor[0],null).Kind==ContextKind.None,"empty snapshot");Check(!ContextPanelModel.Build(new ContextDescriptor[0],null).CanElementEdit,"no selection has no actions");
        var native=new[]{new ContextDescriptor {ShapeId=1,IsTextBox=true},new ContextDescriptor {ShapeId=2,IsShape=true},new ContextDescriptor {ShapeId=3,IsTable=true},new ContextDescriptor {ShapeId=4,IsChart=true},new ContextDescriptor {ShapeId=5,IsConnector=true},new ContextDescriptor {ShapeId=6,IsImage=true}};
        var nativeKinds=new[]{ContextKind.Text,ContextKind.Shape,ContextKind.Table,ContextKind.Chart,ContextKind.Connector,ContextKind.Image};for(int i=0;i<native.Length;i++)Check(Build(native[i]).Kind==nativeKinds[i],"native category");
        var tags=new[]{"text","text-element","text-shape","indicator","process-grid","grid","template","agenda","scene","annotation","connector"};var kinds=new[]{ContextKind.Text,ContextKind.Shape,ContextKind.Shape,ContextKind.Indicator,ContextKind.ProcessGrid,ContextKind.ProcessGrid,ContextKind.Template,ContextKind.Agenda,ContextKind.Shape,ContextKind.Shape,ContextKind.Connector};for(int i=0;i<tags.Length;i++)Check(Build(D(i+1,tags[i])).Kind==kinds[i],"managed category");
        var text=Build(D(1,"text-element"));Check(text.CanText&&text.CanFill&&text.CanOutline&&text.CanFont&&text.CanElementEdit&&text.ActionIds.Contains("fit")&&text.ActionIds.Contains("duplicate-right"),"single managed text capabilities and commands");
        Check(!Build(native[4]).CanElementEdit&&Build(D(1,"connector")).ActionIds.SequenceEqual(new[]{"edit"}),"unmanaged connector does not expose managed editor");
        var grid=Build(D(1,"process-grid"));Check(grid.ActionIds.Contains("grid-row")&&grid.ActionIds.Contains("grid-resize")&&!grid.ActionIds.Contains("fit"),"grid commands do not expose independent text fitting");
        var indicator=Build(D(1,"indicator"));Check(indicator.ActionIds.Contains("indicator-next")&&indicator.ActionIds.Contains("convert-checkbox"),"indicator capabilities");
        var a=D(1,"text-element");var b=D(2,"text-element");b.CanFill=false;var multi=Build(a,b);Check(multi.Kind==ContextKind.Shape&&multi.SelectedCount==2&&multi.CanText&&multi.CanFont&&!multi.CanFill&&multi.CanOutline&&multi.ActionIds.SequenceEqual(new[]{"fit"}),"shared multi capabilities intersect and structural commands disappear");
        var image=new ContextDescriptor {ShapeId=3,IsImage=true,CanOutline=true};var mixed=Build(a,image);Check(mixed.Kind==ContextKind.Mixed&&!mixed.CanText&&!mixed.CanFont&&!mixed.CanFill&&mixed.CanOutline&&!mixed.CanElementEdit,"mixed image text selection keeps only shared formatting");
        var same=Build(D(1,"process-grid"),D(2,"process-grid"));Check(same.Kind==ContextKind.ProcessGrid&&!same.CanElementEdit,"multi-grid structural edits remain disabled");
        var workflow=D(5,"agenda");workflow.ActionIds=new[]{"agenda.refresh","agenda.manage"};var snapshot=Build(workflow);Check(snapshot.Kind==ContextKind.Agenda&&snapshot.ActionIds.SequenceEqual(workflow.ActionIds)&&snapshot.CanElementEdit,"bridge can supply existing workflow actions");workflow.ActionIds[0]="changed";Check(snapshot.ActionIds[0]=="agenda.refresh","snapshot owns immutable action copy");
        Reject(()=>Build(new ContextDescriptor {ShapeId=1,IsChart=true,IsImage=true}),"conflicting native kinds");Reject(()=>Build(D(1),D(1)),"duplicate descriptor identity");Reject(()=>Build(D(0)),"invalid shape identity");var invalid=D(1);invalid.ActionIds=new[]{"run script;"};Reject(()=>Build(invalid),"invalid action identifier");string extended="doc42:"+ContextPanelModel.SelectionKey(12,100,new[]{1})+":cell:2:3";Check(ContextPanelModel.Build(new[]{D(1)},extended).SelectionKey==extended,"opaque document and sub-selection identity extension retained");Reject(()=>ContextPanelModel.Build(new[]{D(1)},""),"missing bridge identity");
        string key=ContextPanelModel.SelectionKey(12,100,new[]{3,1,2});Check(key==ContextPanelModel.SelectionKey(12,100,new[]{2,3,1}),"multi identity independent of selection order");var current=Build(D(1,"text-element"));Check(ContextPanelModel.IsCurrent(current,current.SelectionKey)&&ContextPanelModel.CanExecute(current,current.SelectionKey,"edit"),"live identity permits supported action");Check(!ContextPanelModel.IsCurrent(current,ContextPanelModel.SelectionKey(13,100,new[]{1}))&&!ContextPanelModel.IsCurrent(current,ContextPanelModel.SelectionKey(12,101,new[]{1}))&&!ContextPanelModel.IsCurrent(current,ContextPanelModel.SelectionKey(12,100,new[]{2})),"window slide or object change invalidates snapshot");Check(!ContextPanelModel.CanExecute(current,current.SelectionKey,"grid-row")&&!ContextPanelModel.IsCurrent(null,key)&&!ContextPanelModel.IsCurrent(current,null),"unknown action and missing identity fail closed");
        string cursor=ContextPanelModel.SelectionKey(12,100,new[]{1},1,0);Check(cursor!=ContextPanelModel.SelectionKey(12,100,new[]{1},2,0)&&cursor!=ContextPanelModel.SelectionKey(12,100,new[]{1},1,2),"text caret and range changes invalidate identity");Reject(()=>ContextPanelModel.SelectionKey(12,100,new[]{1,1}),"duplicate key IDs");Reject(()=>ContextPanelModel.SelectionKey(0,100,new[]{1}),"missing window");Reject(()=>ContextPanelModel.SelectionKey(12,0,new[]{1}),"missing slide");Reject(()=>ContextPanelModel.SelectionKey(12,100,new[]{1},1,null),"partial range");Reject(()=>ContextPanelModel.SelectionKey(12,100,new[]{1,2},1,2),"text range across shapes");Reject(()=>ContextPanelModel.SelectionKey(12,100,new[]{1},Int32.MaxValue,1),"text offset overflow");Reject(()=>ContextPanelModel.SelectionKey(12,100,Enumerable.Range(1,501)),"selection count bound");
        Check(MixedValue<int>.From(new int[0]).Kind==MixedValueKind.Empty,"no property values");Reject(()=>{var unused=MixedValue<int>.From(new int[0]).Value;},"no default value for empty input");Check(MixedValue<int>.From(new[]{18,18}).Value==18,"uniform numeric property");Check(MixedValue<int>.From(new[]{18,20}).Kind==MixedValueKind.Mixed,"mixed numeric property");Reject(()=>{var unused=MixedValue<int>.From(new[]{18,20}).Value;},"mixed never presented as a uniform default");Check(MixedValue<string>.From(new[]{"Arial","ARIAL"},StringComparer.OrdinalIgnoreCase).HasValue,"explicit property comparer");Check(MixedValue<string>.From(new string[]{null,null}).HasValue,"uniform nullable value");Reject(()=>MixedValue<int>.From(Enumerable.Range(0,10001)),"mixed enumeration bound");
        var work=new Rectangle(0,0,1200,800);var selected=new Rectangle(200,150,100,100);var panel=new Size(200,150);var placed=ContextPanelModel.Place(selected,work,work,panel);Check(placed.Location==new Point(312,150)&&!placed.IntersectsWith(selected),"prefer right at configured gap");selected=new Rectangle(1050,150,100,100);placed=ContextPanelModel.Place(selected,work,work,panel);Check(placed.Right<=selected.Left&&Fits(placed,work),"right edge uses left placement");selected=new Rectangle(0,150,1200,100);placed=ContextPanelModel.Place(selected,work,work,panel);Check(placed.Top>=selected.Bottom&&Fits(placed,work),"full width uses below");selected=new Rectangle(0,650,1200,100);placed=ContextPanelModel.Place(selected,work,work,panel);Check(placed.Bottom<=selected.Top&&Fits(placed,work),"bottom edge uses above");
        var negative=new Rectangle(-1920,-200,1920,1080);selected=new Rectangle(-200,100,100,100);placed=ContextPanelModel.Place(selected,negative,negative,new Size(320,260));Check(Fits(placed,negative)&&!placed.IntersectsWith(selected),"negative monitor coordinates");var window=new Rectangle(-1800,-100,900,700);placed=ContextPanelModel.Place(new Rectangle(-1000,0,80,80),window,negative,new Size(300,200));Check(Fits(placed,Rectangle.Intersect(window,negative)),"window and monitor work-area intersection");
        placed=ContextPanelModel.Place(work,work,work,new Size(1100,700));Check(Fits(placed,work),"unavoidable overlap remains within work area");placed=ContextPanelModel.Place(new Rectangle(1300,900,100,100),work,work,panel);Check(Fits(placed,work),"off-viewport selection anchors at nearest work-area edge");placed=ContextPanelModel.Place(new Rectangle(200,200,0,20),work,work,panel);Check(Fits(placed,work),"zero-width native caret bounds");
        Reject(()=>ContextPanelModel.Place(selected,work,work,new Size(1300,200)),"oversize panel");Reject(()=>ContextPanelModel.Place(selected,work,new Rectangle(2000,0,100,100),panel),"disjoint work area");Reject(()=>ContextPanelModel.Place(new Rectangle(Int32.MaxValue-5,0,10,10),work,work,panel),"screen rectangle overflow");Reject(()=>ContextPanelModel.Place(selected,work,work,panel,-1),"negative gap");
        // Screen-pixel placement is independent of DPI: exercise scaled viewports and all visible edges.
        foreach(int scale in new[]{1,2,3})for(int x=0;x<=8;x++)for(int y=0;y<=6;y++)
        {
            var area=new Rectangle(-500*scale,-100*scale,1200*scale,800*scale);var target=new Rectangle(area.X+x*125*scale,area.Y+y*100*scale,80*scale,60*scale);var size=new Size(160*scale,100*scale);var result=ContextPanelModel.Place(target,area,area,size,12*scale);Check(Fits(result,area),"scaled viewport containment");Check(!result.IntersectsWith(target),"scaled viewport avoids selection when room exists");
        }
        Console.WriteLine("Context panel model tests passed: "+count);
    }
}

